import type { Metadata } from 'next'
import { headers } from 'next/headers'
import Link from 'next/link'
import NavButton from '@/components/NavButton'
import type { Post } from '@/types'

export const metadata: Metadata = {
  title: 'Home - My Blog',
  description: 'Welcome to my blog homepage',
  openGraph: {
    title: 'Home - My Blog',
  },
}

export default async function HomePage() {
  // Equivalent to `getServerSideProps`: read request data and fetch
  // fresh data on every request (no caching).
  const userAgent = (await headers()).get('user-agent') || ''
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts?_limit=5',
    { cache: 'no-store' }
  ).then((res) => res.json())

  const timestamp = new Date().toISOString()

  return (
    <div>
      <h1>Welcome to My Blog</h1>
      <p>Server-side rendered at: {timestamp}</p>
      <p>Your user agent: {userAgent}</p>

      <h2>Recent Posts</h2>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <Link href={`/blog/${post.id}`}>{post.title}</Link>
          </li>
        ))}
      </ul>

      <NavButton href="/blog">View All Posts</NavButton>
    </div>
  )
}

