import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import BackButton from '@/components/BackButton'
import type { Comment, Post } from '@/types'

type Params = Promise<{ id: string }>

// Equivalent to `getStaticPaths`: pre-render the first 10 posts at build time.
export async function generateStaticParams() {
  const posts: Post[] = await fetch(
    'https://jsonplaceholder.typicode.com/posts'
  ).then((res) => res.json())

  return posts.slice(0, 10).map((post) => ({
    id: post.id.toString(),
  }))
}

// `dynamicParams: true` (the default) replaces `fallback: 'blocking'`:
// ids not generated above are rendered on demand and then cached.
export const dynamicParams = true

interface PostData {
  post: Post
  comments: Comment[]
}

// Equivalent to `getStaticProps` with `revalidate: 300` (ISR).
async function getPost(id: string): Promise<PostData | null> {
  try {
    const [post, comments]: [Post, Comment[]] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }).then((res) => res.json()),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }).then((res) => res.json()),
    ])

    // An unknown id resolves to an empty object on this API.
    if (!post || !post.id) {
      return null
    }

    return { post, comments }
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: {
  params: Params
}): Promise<Metadata> {
  const { id } = await params
  const data = await getPost(id)

  if (!data) {
    return { title: 'Post Not Found - My Blog' }
  }

  const { post } = data
  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPost({ params }: { params: Params }) {
  const { id } = await params
  const data = await getPost(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

